// driveInbox-Objekt -> ein Item pro Eintrag mit status 'pending'.
// Verarbeitete Eintraege bleiben stehen (Muster entityInbox: Status-Feld, kein Loeschen),
// daher ist der Poll idempotent.
let daten = null;
try { daten = $input.first().json; } catch (e) { /* leerer Lauf */ }
if (daten && typeof daten === 'object' && !Array.isArray(daten) && Object.keys(daten).length === 1 && 'data' in daten) daten = daten.data;
if (!daten || typeof daten !== 'object' || Array.isArray(daten)) return [];

const items = [];
for (const [key, v] of Object.entries(daten)) {
  if (!v || v.status !== 'pending') continue;
  items.push({ json: {
    docId: v.docId || key,
    inboxKey: key,
    dateiname: v.dateiname || '',
    mimeType: v.mimeType || '',
    hash: v.hash || '',
    duplikat_verdacht: v.duplikat_verdacht === true,
    // Text kommt aus dem Queue-Eintrag (clientseitig extrahiert) — Datei wird NICHT neu geladen.
    text: String(v.text || '').slice(0, 6000)
  }});
}
return items;

// Striktes JSON parsen + Confidence-Gate.
// Parse-Fehler ODER confidence < 0.6 -> status 'review_noetig' (normaler Pfad, Inbox 'processed').
// Harter API-/HTTP-Fehler -> ok:false (Fehlerpfad: Doc 'review_noetig' + Fehlertext, Inbox 'error').
const meta = $('Claude-Request bauen').item.json;
const resp = $json;
const jetzt = $now.toISO();

const antwortText = (resp && Array.isArray(resp.content) && resp.content[0] && typeof resp.content[0].text === 'string')
  ? resp.content[0].text : null;

if (!antwortText) {
  const fehler = 'Claude-API-Fehler: ' + JSON.stringify((resp && (resp.error || resp)) || 'keine Antwort').slice(0, 500);
  return { json: { ok: false, docId: meta.docId, inboxKey: meta.inboxKey, status: 'review_noetig', vorschlag: null, fehler: fehler, aktualisiert: jetzt } };
}

let parsed = null, parseFehler = null;
try {
  let t = antwortText.trim();
  const zaun = t.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (zaun) t = zaun[1].trim();
  parsed = JSON.parse(t);
} catch (e) { parseFehler = 'JSON-Parse-Fehler: ' + e.message; }

if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
  return { json: { ok: true, docId: meta.docId, inboxKey: meta.inboxKey, status: 'review_noetig', vorschlag: null, fehler: parseFehler || 'Antwort war kein JSON-Objekt', aktualisiert: jetzt } };
}

const conf = Math.max(0, Math.min(1, Number(parsed.confidence) || 0));
const vorschlag = {
  bereich: String(parsed.bereich || 'Eingang'),
  unterordner: String(parsed.unterordner || ''),
  thema: String(parsed.thema || ''),
  tags: Array.isArray(parsed.tags) ? parsed.tags.slice(0, 5).map(t => String(t).toLowerCase()) : [],
  titel_vorschlag: String(parsed.titel_vorschlag || meta.dateiname || ''),
  confidence: conf,
  begruendung: String(parsed.begruendung || ''),
  duplikat_verdacht: parsed.duplikat_verdacht === true || meta.duplikat_verdacht === true
};
const status = conf >= 0.6 ? 'klassifiziert' : 'review_noetig';

return { json: { ok: true, docId: meta.docId, inboxKey: meta.inboxKey, status: status, vorschlag: vorschlag, fehler: null, aktualisiert: jetzt } };
